// CREATIONAL: Factory creates payment processors
@Component
class PaymentProcessorFactory {
    PaymentProcessor create(String type) {
        return switch(type) {
            case "CARD" -> new CardProcessor();
            case "UPI" -> new UpiProcessor();
            default -> throw new IllegalArgumentException("Unknown type");
        };
    }
}

// STRUCTURAL: Decorator adds logging to cart operations
class LoggingCartService implements CartService {
    private final CartService delegate;
    void addItem(Item item) {
        log.info("Adding item: {}", item);
        delegate.addItem(item);  // wraps actual service
    }
}

// BEHAVIORAL: Strategy for discount calculation
interface DiscountStrategy {
    BigDecimal apply(BigDecimal total);
}

class SeasonalDiscount implements DiscountStrategy {
    public BigDecimal apply(BigDecimal total) {
        return total.multiply(new BigDecimal("0.9"));  // 10% off
    }
}

// Over-engineered: Strategy pattern for a single discount rule
interface DiscountStrategy {
    double apply(double amount);
}

class FlatDiscountStrategy implements DiscountStrategy {
    public double apply(double amount) {
        return amount * 0.9; // 10% off
    }
}

class CartService {
    private final DiscountStrategy strategy;

    public CartService(DiscountStrategy strategy) {
        this.strategy = strategy;
    }

    public double calculateTotal(List<CartItem> items) {
        double sum = items.stream().mapToDouble(CartItem::price).sum();
        return strategy.apply(sum); // Unnecessary abstraction for one rule
    }
}

// Simple approach: direct calculation
class SimpleCartService {
    public double calculateTotal(List<CartItem> items) {
        double sum = items.stream().mapToDouble(CartItem::price).sum();
        return sum * 0.9; // Clear, 3 classes become 1 method
    }
}
